import re
from collections import deque

def solve(env, goal):
    goal_l = goal.lower()
    m = re.search(r'(?:look at|examine|inspect|see)\s+(?:the\s+|a\s+)?([a-z]+)', goal_l)
    obj_type = m.group(1) if m else "book"
    m = re.search(r'(?:under|with|by|using)\s+(?:the\s+|a\s+)?([a-z]+)', goal_l)
    lamp_type = m.group(1) if m else "desklamp"

    def parse_items(text):
        items = []
        for m in re.finditer(r'\b([a-z]+)\s+(\d+)\b', text):
            items.append((m.group(1), m.group(2), m.group(1) + " " + m.group(2)))
        return items

    def first_type(items, want):
        for base, ident, full in items:
            if base == want:
                return full
        return None

    def inv(self_text):
        return [full for (b, i, full) in parse_items(self_text)]

    # collect receptacles from room description (exclude objects that are clearly items)
    room = env.observation
    receptacles = []
    for base, ident, full in parse_items(room):
        if base in ("bed", "desk", "drawer", "cabinet", "shelf", "fridge", "microwave",
                    "safe", "garbagecan", "laundryhamper", "table", "sofa", "counter",
                    "sink", "box", "chest", "closet", "dresser", "tabletop", "partially"):
            receptacles.append(full)
    # dedupe preserving order
    seen = set()
    receptacles = [r for r in receptacles if not (r in seen or seen.add(r))]

    def look_here():
        return env.step("look")

    def go(loc):
        return env.step("go to " + loc)

    def take(full, loc):
        return env.step("take " + full + " from " + loc)

    def inventory():
        return inv(env.step("inventory"))

    found_obj = None
    found_obj_loc = None
    found_lamp = None
    found_lamp_loc = None

    # First pass: go to each receptacle, look (no open), record matches and nested receptacles
    to_explore = deque(receptacles)
    explored = set()
    while to_explore:
        loc = to_explore.popleft()
        if loc in explored:
            continue
        explored.add(loc)
        go(loc)
        fb = look_here()
        items = parse_items(fb)
        for base, ident, full in items:
            if base == obj_type and not found_obj:
                found_obj, found_obj_loc = full, loc
            if base == lamp_type and not found_lamp:
                found_lamp, found_lamp_loc = full, loc
            if base in ("drawer", "cabinet", "shelf", "fridge", "microwave", "safe",
                        "box", "chest", "closet", "dresser") and full not in explored:
                to_explore.append(full)
        if found_obj and found_lamp:
            break

    # Second pass: open closed receptacles and re-look
    if not found_obj or not found_lamp:
        for loc in receptacles:
            go(loc)
            fb = look_here()
            items = parse_items(fb)
            for base, ident, full in items:
                if base == obj_type and not found_obj:
                    found_obj, found_obj_loc = full, loc
                if base == lamp_type and not found_lamp:
                    found_lamp, found_lamp_loc = full, loc
            if not found_obj:
                fb = env.step("open " + loc)
                fb = look_here()
                items = parse_items(fb)
                for base, ident, full in items:
                    if base == obj_type and not found_obj:
                        found_obj, found_obj_loc = full, loc
                    if base == lamp_type and not found_lamp:
                        found_lamp, found_lamp_loc = full, loc
            if found_obj and found_lamp:
                break

    # Check inventory too
    if not found_obj:
        for full in inventory():
            if obj_type in full:
                found_obj = full
                break
    if not found_lamp:
        for full in inventory():
            if lamp_type in full or "lamp" in full:
                found_lamp = full
                break

    if not found_obj:
        return "Nothing happens."
    if not found_lamp:
        found_lamp = lamp_type + " 1"

    # Acquire object if not already held
    if found_obj not in inventory():
        if found_obj_loc:
            go(found_obj_loc)
            fb = env.step("open " + found_obj_loc)
            fb = look_here()
            if found_obj not in fb:
                fb = env.step("open " + found_obj_loc)
                fb = look_here()
            take(found_obj, found_obj_loc)
        else:
            # search for it
            for loc in receptacles:
                go(loc)
                fb = look_here()
                if found_obj in fb:
                    take(found_obj, loc)
                    break
                fb = env.step("open " + loc)
                fb = look_here()
                if found_obj in fb:
                    take(found_obj, loc)
                    break

    # Turn on lamp
    if found_lamp_loc:
        go(found_lamp_loc)
    env.step("use " + found_lamp)

    # Examine while holding
    if found_obj not in inventory():
        for loc in receptacles:
            go(loc)
            fb = look_here()
            if found_obj in fb:
                take(found_obj, loc)
                break
            fb = env.step("open " + loc)
            fb = look_here()
            if found_obj in fb:
                take(found_obj, loc)
                break

    return env.step("examine " + found_obj)
